Here is a concise summary of the reasoning steps:

To create a functional language for querying and data transformation, I started by defining the basic grammar for `KickLang`. I used Backus-Naur Form (BNF) to outline the essential components of the language, including data types, functions, and syntax for property specifications and conditions. I extended the grammar to include logical operations, entity properties, and relation representations.

I then defined the data model as a property graph, where entities have IDs, types, and properties, and relations connect entities with relation types. I decided to start with a simple representation of the graph in memory using dictionaries.

Next, I chose to implement `KickLang` using Python, focusing on building a basic parser and interpreter. I represented conditions as lambda functions and combined them using logical operations. I defined the functions `find`, `filter`, `related`, and `related_some` to query the graph.

## Final Solution

```python
import networkx as nx
from typing import Dict, List

class Entity:
    def __init__(self, id: str, type: str, properties: Dict[str, str]):
        self.id = id
        self.type = type
        self.properties = properties

class Relation:
    def __init__(self, from_node: str, to_node: str, relation_type: str):
        self.from_node = from_node
        self.to_node = to_node
        self.relation_type = relation_type

class Graph:
    def __init__(self):
        self.entities = {}
        self.relations = []

    def add_entity(self, entity: Entity):
        self.entities[entity.id] = entity

    def add_relation(self, relation: Relation):
        self.relations.append(relation)

def find(graph: Graph, type: str, properties: Dict[str, str]) -> List[str]:
    matches = []
    for entity_id, entity in graph.entities.items():
        if entity.type == type and all(entity.properties.get(key) == value for key, value in properties.items()):
            matches.append(entity_id)
    return matches

def filter(graph: Graph, entities: List[str], condition: str) -> List[str]:
    matches = []
    for entity_id in entities:
        entity = graph.entities[entity_id]
        if evaluate_condition(entity.properties, condition):
            matches.append(entity_id)
    return matches

def related(graph: Graph, entity_id: str, relation: str) -> List[str]:
    matches = []
    for relation in graph.relations:
        if relation.from_node == entity_id and relation.relation_type == relation:
            matches.append(relation.to_node)
    return matches

def related_some(graph: Graph, entities: List[str], relation: str) -> bool:
    for entity_id in entities:
        if related(graph, entity_id, relation):
            return True
    return False

def evaluate_condition(properties: Dict[str, str], condition: str) -> bool:
    # Evaluate the condition as a Python expression
    try:
        return eval(condition, {'__builtins__': None}, properties)
    except Exception:
        return False

# Create a sample graph
graph = Graph()
graph.add_entity(Entity('1', 'Person', {'name': 'Alice', 'age': '30', 'location': 'New York'}))
graph.add_entity(Entity('2', 'Person', {'name': 'Bob', 'age': '25', 'location': 'Los Angeles'}))

graph.add_relation(Relation('1', '2', 'friends'))

# Test the functions
print(find(graph, 'Person', {'name': 'Alice'}))  # ['1']
print(filter(graph.entities.keys(), ['1'], 'age > 30'))  # ['1']
print(related(graph, '1', 'friends'))  # ['2']
print(related_some(graph.entities.keys(), ['1'], 'friends'))  # True
```
